changeSet.sql:
UPDATE outbox_messages SET partition_key = aggregate_id WHERE partition_key IS NULL;
ALTER TABLE outbox_messages ALTER COLUMN partition_key SET NOT NULL;

CREATE SEQUENCE IF NOT EXISTS profile_outbox_message_order;
ALTER TABLE outbox_messages ADD COLUMN IF NOT EXISTS sequence_number BIGINT;
WITH ordered AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY created_at, id) AS position
    FROM outbox_messages
    WHERE sequence_number IS NULL
)
UPDATE outbox_messages m SET sequence_number = ordered.position FROM ordered WHERE m.id = ordered.id;
SELECT setval('profile_outbox_message_order', COALESCE(MAX(sequence_number), 1), COUNT(*) > 0) FROM outbox_messages;
ALTER SEQUENCE profile_outbox_message_order OWNED BY outbox_messages.sequence_number;
ALTER TABLE outbox_messages ALTER COLUMN sequence_number SET DEFAULT nextval('profile_outbox_message_order');
ALTER TABLE outbox_messages ALTER COLUMN sequence_number SET NOT NULL;

CREATE INDEX IF NOT EXISTS idx_profile_outbox_unpublished ON outbox_messages (topic, partition_key, sequence_number)
    WHERE status <> 'PUBLISHED';
ALTER TABLE outbox_messages ADD CONSTRAINT ck_profile_outbox_status CHECK (status IN ('PENDING', 'PUBLISHED', 'FAILED'));
